import{_ as a,o,c as r,a3 as d}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Lembrar lei de regência da RPV por devedor","description":"","frontmatter":{"title":"Lembrar lei de regência da RPV por devedor","id":"rupe-rpv-lei-devedor","plataforma":"RUPE","grupo":"RUPE","plano":"free","desde":"1.10.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/rupe-rpv-lei-devedor.md","filePath":"funcionalidades/rupe-rpv-lei-devedor.md"}'),s={name:"funcionalidades/rupe-rpv-lei-devedor.md"};function i(l,e,n,p,c,t){return o(),r("div",null,e[0]||(e[0]=[d('<h1 id="lembrar-lei-de-regencia-da-rpv-por-devedor" tabindex="-1">Lembrar lei de regência da RPV por devedor <a class="header-anchor" href="#lembrar-lei-de-regencia-da-rpv-por-devedor" aria-label="Permalink to &quot;Lembrar lei de regência da RPV por devedor&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No cadastro de RPV do RUPE, a seção &quot;Lei de Regência da Obrigação de Pequeno Valor do Devedor&quot; pede sempre os mesmos dados para o mesmo devedor: se ele possui lei própria e, se possuir, o número, o ano e a data de publicação da lei. O eploc lembra essa resposta para cada devedor e a preenche sozinho nas próximas RPVs dele.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>RUPE</strong> (<code>rupe.tjmg.jus.br</code>), tela de cadastro de RPV. As leis guardadas ficam nas configurações do eploc, no card do recurso (&quot;Gerenciar leis por devedor&quot;).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Cadastre uma RPV normalmente, preenchendo a seção da lei de regência do devedor (ou respondendo que ele não possui lei própria), e clique em <strong>Salvar</strong>.</li><li>Na próxima RPV do mesmo devedor, assim que ele for selecionado, a seção já vem preenchida. Os campos preenchidos pelo eploc ficam destacados em azul; passe o mouse sobre eles para ver de qual devedor veio a lei.</li><li>Se a lei mudou, corrija os campos e salve a RPV: o eploc passa a usar os dados novos.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><p>No card, <strong>Gerenciar leis por devedor</strong> lista os devedores guardados e permite corrigir a lei de cada um ou esquecê-lo. No topo dele, dá para incluir a lei de um devedor habitual antes mesmo da primeira RPV: informe o nome, o CPF/CNPJ (opcional, mas recomendado), se ele possui lei própria e, se possuir, número, ano e data de publicação, e clique em <strong>Incluir</strong>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O devedor é reconhecido pelo CPF ou CNPJ. Sem documento, pelo nome.</li><li>O eploc só guarda a lei quando a RPV é salva com a seção completa (número, ano com quatro dígitos e data no formato dd/mm/aaaa), ou com a resposta de que o devedor não possui lei própria.</li><li>Campos que já tinham valor, como os de uma RPV salva antes, não são alterados.</li><li>Confira a seção antes de salvar, como em qualquer preenchimento automático.</li></ul>',12)]))}const v=a(s,[["render",i]]);export{m as __pageData,v as default};
